def regex_search(pattern: str, text: str) -> bool:
    if pattern == "":
        return True

    n = len(pattern)
    pos = 0

    # ---------- Parser ----------
    def parse_alt():
        nonlocal pos
        options = [parse_concat()]
        while pos < n and pattern[pos] == '|':
            pos += 1
            options.append(parse_concat())
        if len(options) == 1:
            return options[0]
        return ('alt', options)

    def parse_concat():
        nonlocal pos
        items = []
        while pos < n and pattern[pos] not in '|)':
            items.append(parse_quantified())
        if len(items) == 0:
            return ('concat', [])
        if len(items) == 1:
            return items[0]
        return ('concat', items)

    def parse_quantified():
        nonlocal pos
        element = parse_element()
        if pos < n and pattern[pos] in '*+?':
            if element[0] in ('start', 'end'):
                raise ValueError("Quantifier on assertion")
            q = pattern[pos]
            pos += 1
            if pos < n and pattern[pos] in '*+?':
                raise ValueError("Doubled quantifier")
            if q == '*':
                return ('repeat', element, 0, None)
            elif q == '+':
                return ('repeat', element, 1, None)
            else:
                return ('repeat', element, 0, 1)
        return element

    def parse_element():
        nonlocal pos
        c = pattern[pos]
        if c == '.':
            pos += 1
            return ('dot',)
        elif c == '^':
            pos += 1
            return ('start',)
        elif c == '$':
            pos += 1
            return ('end',)
        elif c == '[':
            return parse_char_class()
        elif c == '\\':
            if pos + 1 >= n:
                raise ValueError("Trailing backslash")
            escaped = pattern[pos + 1]
            pos += 2
            return ('char', escaped)
        elif c == '(':
            pos += 1
            inner = parse_alt()
            if pos >= n or pattern[pos] != ')':
                raise ValueError("Unmatched parenthesis")
            pos += 1
            return inner
        elif c in '*+?':
            raise ValueError("Quantifier without preceding element")
        else:
            pos += 1
            return ('char', c)

    def parse_char_class():
        nonlocal pos
        pos += 1
        negated = False
        if pos < n and pattern[pos] == '^':
            negated = True
            pos += 1
        if pos < n and pattern[pos] == ']':
            raise ValueError("Empty character class")
        chars = set()
        while pos < n and pattern[pos] != ']':
            if pattern[pos] == '\\':
                if pos + 1 >= n:
                    raise ValueError("Trailing backslash")
                c1 = pattern[pos + 1]
                pos += 2
            else:
                c1 = pattern[pos]
                pos += 1
            if pos < n and pattern[pos] == '-' and pos + 1 < n and pattern[pos + 1] != ']':
                pos += 1
                if pattern[pos] == '\\':
                    if pos + 1 >= n:
                        raise ValueError("Trailing backslash")
                    c2 = pattern[pos + 1]
                    pos += 2
                else:
                    c2 = pattern[pos]
                    pos += 1
                if ord(c1) > ord(c2):
                    raise ValueError("Invalid range")
                for code in range(ord(c1), ord(c2) + 1):
                    chars.add(chr(code))
            else:
                chars.add(c1)
        if pos >= n:
            raise ValueError("Unclosed character class")
        pos += 1
        return ('class', chars, negated)

    ast = parse_alt()
    if pos != n:
        raise ValueError("Unexpected character")

    # ---------- NFA Construction ----------
    state_counter = [0]
    transitions = {}

    def new_state():
        s = state_counter[0]
        state_counter[0] += 1
        transitions[s] = []
        return s

    def add_trans(s, t, data, target):
        transitions[s].append((t, data, target))

    def build_node(node):
        tag = node[0]
        if tag == 'char':
            s = new_state()
            e = new_state()
            add_trans(s, 'char', node[1], e)
            return (s, e)
        elif tag == 'dot':
            s = new_state()
            e = new_state()
            add_trans(s, 'any', None, e)
            return (s, e)
        elif tag == 'class':
            s = new_state()
            e = new_state()
            if node[2]:
                add_trans(s, 'neg_class', node[1], e)
            else:
                add_trans(s, 'class', node[1], e)
            return (s, e)
        elif tag == 'start':
            s = new_state()
            e = new_state()
            add_trans(s, 'start', None, e)
            return (s, e)
        elif tag == 'end':
            s = new_state()
            e = new_state()
            add_trans(s, 'end', None, e)
            return (s, e)
        elif tag == 'concat':
            items = node[1]
            if not items:
                s = new_state()
                e = new_state()
                add_trans(s, 'eps', None, e)
                return (s, e)
            first_start = None
            prev_end = None
            for i, item in enumerate(items):
                s, e = build_node(item)
                if i == 0:
                    first_start = s
                else:
                    add_trans(prev_end, 'eps', None, s)
                prev_end = e
            return (first_start, prev_end)
        elif tag == 'alt':
            options = node[1]
            s = new_state()
            e = new_state()
            for opt in options:
                os_, oe = build_node(opt)
                add_trans(s, 'eps', None, os_)
                add_trans(oe, 'eps', None, e)
            return (s, e)
        elif tag == 'repeat':
            item, min_count, max_count = node[1], node[2], node[3]
            s = new_state()
            e = new_state()
            is_, ie = build_node(item)
            if max_count is None:
                if min_count == 0:
                    add_trans(s, 'eps', None, is_)
                    add_trans(s, 'eps', None, e)
                else:
                    add_trans(s, 'eps', None, is_)
                add_trans(ie, 'eps', None, is_)
                add_trans(ie, 'eps', None, e)
            else:
                add_trans(s, 'eps', None, is_)
                add_trans(ie, 'eps', None, e)
                if min_count == 0:
                    add_trans(s, 'eps', None, e)
            return (s, e)
        else:
            raise ValueError(f"Unknown node: {tag}")

    start_state, end_state = build_node(ast)

    # ---------- NFA Simulation (state-set tracking) ----------
    text_len = len(text)

    def closure(states, p):
        result = set(states)
        stack = list(states)
        while stack:
            st = stack.pop()
            for (t, data, target) in transitions[st]:
                if t == 'eps':
                    if target not in result:
                        result.add(target)
                        stack.append(target)
                elif t == 'start' and p == 0:
                    if target not in result:
                        result.add(target)
                        stack.append(target)
                elif t == 'end' and p == text_len:
                    if target not in result:
                        result.add(target)
                        stack.append(target)
        return result

    prev_next = set()
    for i in range(text_len + 1):
        if i == 0:
            active = closure({start_state}, 0)
        else:
            active = closure(prev_next | {start_state}, i)
        if end_state in active:
            return True
        if i < text_len:
            ch = text[i]
            prev_next = set()
            for st in active:
                for (t, data, target) in transitions[st]:
                    if t == 'char' and data == ch:
                        prev_next.add(target)
                    elif t == 'any':
                        prev_next.add(target)
                    elif t == 'class' and ch in data:
                        prev_next.add(target)
                    elif t == 'neg_class' and ch not in data:
                        prev_next.add(target)
    return False
