def regex_search(pattern: str, text: str) -> bool:
    if pattern == "":
        return True

    n = len(pattern)
    pos = 0

    # --- Parser ---
    def parse_alt():
        nonlocal pos
        options = [parse_concat()]
        while pos < n and pattern[pos] == '|':
            pos += 1
            options.append(parse_concat())
        if len(options) == 1:
            return options[0]
        return ('alt', options)

    def parse_concat():
        nonlocal pos
        items = []
        while pos < n and pattern[pos] not in '|)':
            items.append(parse_quantified())
        if len(items) == 0:
            return ('concat', [])
        if len(items) == 1:
            return items[0]
        return ('concat', items)

    def parse_quantified():
        nonlocal pos
        element = parse_element()
        if element[0] in ('start', 'end'):
            # Can't have quantifier on assertion, but only if there IS a quantifier
            pass  # We'll check below
        if pos < n and pattern[pos] in '*+?':
            if element[0] in ('start', 'end'):
                raise ValueError("Quantifier on assertion")
            q = pattern[pos]
            pos += 1
            if pos < n and pattern[pos] in '*+?':
                raise ValueError("Doubled quantifier")
            if q == '*':
                return ('repeat', element, 0, None)
            elif q == '+':
                return ('repeat', element, 1, None)
            else:
                return ('repeat', element, 0, 1)
        return element

    def parse_element():
        nonlocal pos
        c = pattern[pos]
        if c == '.':
            pos += 1
            return ('dot',)
        elif c == '^':
            pos += 1
            return ('start',)
        elif c == '$':
            pos += 1
            return ('end',)
        elif c == '[':
            return parse_char_class()
        elif c == '\\':
            if pos + 1 >= n:
                raise ValueError("Trailing backslash")
            escaped = pattern[pos + 1]
            pos += 2
            return ('char', escaped)
        elif c == '(':
            pos += 1
            inner = parse_alt()
            if pos >= n or pattern[pos] != ')':
                raise ValueError("Unmatched parenthesis")
            pos += 1
            return inner
        elif c in '*+?':
            raise ValueError("Quantifier without preceding element")
        else:
            pos += 1
            return ('char', c)

    def parse_char_class():
        nonlocal pos
        pos += 1  # skip '['
        negated = False
        if pos < n and pattern[pos] == '^':
            negated = True
            pos += 1

        if pos < n and pattern[pos] == ']':
            raise ValueError("Empty character class")

        chars = set()
        while pos < n and pattern[pos] != ']':
            if pattern[pos] == '\\':
                if pos + 1 >= n:
                    raise ValueError("Trailing backslash in class")
                c1 = pattern[pos + 1]
                pos += 2
            else:
                c1 = pattern[pos]
                pos += 1

            if pos < n and pattern[pos] == '-' and pos + 1 < n and pattern[pos + 1] != ']':
                pos += 1  # skip '-'
                if pattern[pos] == '\\':
                    if pos + 1 >= n:
                        raise ValueError("Trailing backslash in class")
                    c2 = pattern[pos + 1]
                    pos += 2
                else:
                    c2 = pattern[pos]
                    pos += 1
                if ord(c1) > ord(c2):
                    raise ValueError("Invalid range")
                for code in range(ord(c1), ord(c2) + 1):
                    chars.add(chr(code))
            else:
                chars.add(c1)

        if pos >= n:
            raise ValueError("Unclosed character class")
        pos += 1  # skip ']'

